<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use PHPUnit\Framework\Attributes\AllowMockObjectsWithoutExpectations;
use GuzzleHttp\ClientInterface;
use GuzzleHttp\Psr7\Response;
use Civi\Lughauth\Shared\AppConfig;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Features\OAuth\DelegateLogin\Infrastructure\Provider\GitHubOAuthProvider;

#[AllowMockObjectsWithoutExpectations]
final class GitHubOAuthProviderUnitTest extends TestCase
{
    public function testDelegatedUrlContainsExpectedQuery(): void
    {
        $provider = $this->createProvider($this->createMock(ClientInterface::class));

        $endpoint = $provider->delegeatedUrl('https://app.local/delegate/callback', 'state-123');
        $query = [];
        parse_str(parse_url($endpoint->url, PHP_URL_QUERY) ?: '', $query);

        $this->assertEquals('GET', $endpoint->method);
        $this->assertEquals('abc', $query['client_id'] ?? null);
        $this->assertEquals('state-123', $query['state'] ?? null);
        $this->assertEquals('user:email read:user', $query['scope'] ?? null);
        $this->assertEquals('https://app.local/delegate/callback', $query['redirect_uri'] ?? null);
    }

    public function testAuthorizeUsesUserEmailWhenAvailable(): void
    {
        $http = $this->createMock(ClientInterface::class);
        $http->expects($this->exactly(2))
            ->method('request')
            ->willReturnOnConsecutiveCalls(
                new Response(200, [], '{"access_token":"token-1"}'),
                new Response(200, [], '{"id":10,"email":"dev@example.com","name":"Dev","avatar_url":"https://img.local/a.png"}')
            );

        $provider = $this->createProvider($http);
        $user = $provider->authorize('https://app.local/delegate/callback', ['code' => 'oauth-code']);

        $this->assertNotNull($user);
        $this->assertEquals('10', $user->providerUserId);
        $this->assertEquals('dev@example.com', $user->email);
        $this->assertEquals('Dev', $user->name);
        $this->assertEquals('https://img.local/a.png', $user->pictureUrl);
        $this->assertTrue($user->emailVerified);
    }

    public function testAuthorizeUsesPrimaryEmailEndpointWhenProfileEmailIsMissing(): void
    {
        $http = $this->createMock(ClientInterface::class);
        $http->expects($this->exactly(3))
            ->method('request')
            ->willReturnOnConsecutiveCalls(
                new Response(200, [], '{"access_token":"token-2"}'),
                new Response(200, [], '{"id":11,"login":"dev-user"}'),
                new Response(200, [], '[{"email":"private@example.com","primary":true,"verified":true}]')
            );

        $provider = $this->createProvider($http);
        $user = $provider->authorize('https://app.local/delegate/callback', ['code' => 'oauth-code']);

        $this->assertNotNull($user);
        $this->assertEquals('private@example.com', $user->email);
        $this->assertEquals('dev-user', $user->name);
        $this->assertTrue($user->emailVerified);
    }

    public function testAuthorizeReturnsNullOnNetworkError(): void
    {
        $http = $this->createMock(ClientInterface::class);
        $http->method('request')->willThrowException(new RuntimeException('network'));

        $provider = $this->createProvider($http);
        $user = $provider->authorize('https://app.local/delegate/callback', ['code' => 'oauth-code']);

        $this->assertNull($user);
    }

    private function createProvider(ClientInterface $http): GitHubOAuthProvider
    {
        $config = $this->createMock(AppConfig::class);
        $config->method('get')->willReturn('https://assets.local');

        $context = $this->createMock(Context::class);
        $context->method('getBaseUrl')->willReturn('https://app.local');

        return new GitHubOAuthProvider(
            $config,
            $context,
            'github-provider',
            'abc',
            'secret',
            $http
        );
    }
}
